export function boundToolResultText(text: string, maxBytes: number): string {
  return Buffer.byteLength(text) > maxBytes ? `${text.slice(0, maxBytes)}\n[truncated]` : text;
}

export function looksLikeBinary(buffer: Buffer): boolean {
  return buffer.subarray(0, 800).includes(0);
}

export function resolveResultMaxBytesForCall(call: { scripted?: boolean }): number {
  return call.scripted ? 40_000 : 12_000;
}

